<section class="page-hero"><div class="container"><span class="eyebrow">Digital marketplace</span><h1>Products for better work.</h1></div></section>
<section class="content-section"><div class="container">
<div class="shop-toolbar"><form method="get"><label class="sr-only" for="q">Search</label><input id="q" name="q" value="<?= $this->escape($_GET['q'] ?? '') ?>" placeholder="Search products"><button class="button" type="submit">Search</button></form>
<form method="get"><label class="sr-only" for="category">Category</label><select id="category" name="category" onchange="this.form.submit()"><option value="">All categories</option><?php foreach($categories as $category): ?><option value="<?= $this->escape($category['slug']) ?>" <?= ($_GET['category'] ?? '') === $category['slug'] ? 'selected' : '' ?>><?= $this->escape($category['name']) ?></option><?php endforeach ?></select></form></div>
<?php if (!$products): ?><div class="empty-state"><i data-lucide="package-open"></i><h2>No products found</h2><p>Try another search or category.</p></div>
<?php else:?><div class="product-grid"><?php foreach($products as $product): $productImage = $this->imageUrl($product['thumbnail'] ?? ''); ?><article class="product-card"><div class="product-image"><?php if ($productImage !== ''): ?><img src="<?= $this->escape($productImage) ?>" alt=""><?php else: ?><span><?= $this->escape(substr($product['name'],0,1)) ?></span><?php endif ?></div><div class="product-body"><span class="product-category"><?= $this->escape($product['category_name'] ?: 'Digital Product') ?></span><h2><?= $this->escape($product['name']) ?></h2><p><?= $this->escape($product['short_description'] ?: '') ?></p><div class="product-footer"><strong><?= $this->escape($product['currency']) ?> <?= number_format((float)$product['price'],2) ?></strong><a href="<?= $this->escape($this->productUrl($product)) ?>">View details</a></div></div></article><?php endforeach ?></div><?php endif ?>
</div></section>
